using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using Newtonsoft.Json;
public static class F1FirstLightApply {
 const string E="Assets/Afrer_Seconds/05.Model/Environment/1F/";const string P="Assets/Afrer_Seconds/06.Data/Rendering/1F/FL_FirstLightBloom.asset";
 static string Root=>Path.GetFullPath(Application.dataPath+"/../../..");static string Out=>Root+"/Docs/Review/2026-11-13_1F_FirstLight/";
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_1F_Factory.unity"))throw new Exception("Saved 1F edit required");if(AssetDatabase.LoadAssetAtPath<VolumeProfile>(P)||GameObject.Find("1F_AbandonedFactory/Lighting/FirstLightBloom"))throw new Exception("First apply already done");if(!File.Exists(Out+"before_transforms.json"))throw new Exception("Baseline required");var camera=Camera.main;var data=camera.GetUniversalAdditionalCameraData();var pipeline=GraphicsSettings.currentRenderPipeline as UniversalRenderPipelineAsset;if(!pipeline||!pipeline.supportsHDR||!camera.allowHDR||!data.renderPostProcessing||(data.volumeLayerMask.value&1)==0)throw new Exception("HDR/postprocessing/layer prerequisite changed");
 File.Copy(Root+"/SourceAssets/F1_FirstLight/FS_SunsetSky.shader",E+"FS_SunsetSky.shader",true);AssetDatabase.ImportAsset(E+"FS_SunsetSky.shader",ImportAssetOptions.ForceSynchronousImport|ImportAssetOptions.ForceUpdate);var shader=AssetDatabase.LoadAssetAtPath<Shader>(E+"FS_SunsetSky.shader");if(ShaderUtil.GetShaderMessages(shader).Any(m=>m.severity.ToString()=="Error"))throw new Exception("Sky shader error");
 var mat=AssetDatabase.LoadAssetAtPath<Material>(E+"Materials/FS_SunsetSky.mat");Undo.RecordObject(mat,"Emphasize first sunlight");mat.SetFloat("_SunRadius",.026f);mat.SetColor("_SunColor",new Color(7.5f,5.2f,2.8f));mat.SetFloat("_CoronaStrength",1.2f);mat.SetFloat("_HaloStrength",.6f);mat.SetFloat("_HaloWidth",.16f);EditorUtility.SetDirty(mat);
 if(!AssetDatabase.IsValidFolder("Assets/Afrer_Seconds/06.Data/Rendering/1F"))AssetDatabase.CreateFolder("Assets/Afrer_Seconds/06.Data/Rendering","1F");var profile=ScriptableObject.CreateInstance<VolumeProfile>();profile.name="FL_FirstLightBloom";AssetDatabase.CreateAsset(profile,P);var bloom=profile.Add<Bloom>(true);bloom.name="FirstLightBloom";bloom.threshold.Override(1.2f);bloom.intensity.Override(.7f);bloom.scatter.Override(.78f);bloom.tint.Override(new Color(1,.96f,.88f));bloom.clamp.Override(32f);bloom.highQualityFiltering.Override(true);AssetDatabase.AddObjectToAsset(bloom,profile);EditorUtility.SetDirty(profile);
 var parent=GameObject.Find("1F_AbandonedFactory/Lighting");if(!parent)throw new Exception("Lighting parent missing");var go=new GameObject("FirstLightBloom");Undo.RegisterCreatedObjectUndo(go,"Add 1F sunlight bloom");go.transform.SetParent(parent.transform,false);go.layer=0;var volume=go.AddComponent<Volume>();volume.isGlobal=true;volume.priority=10;volume.weight=1;volume.sharedProfile=profile;
 AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);DynamicGI.UpdateEnvironment();var result=new{saved=true,sunRadius=mat.GetFloat("_SunRadius"),diameterRatio=.026f/.009f,profile=P,bloomThreshold=bloom.threshold.value,bloomIntensity=bloom.intensity.value,bloomScatter=bloom.scatter.value,cameraChanged=false,newTransforms=1};File.WriteAllText(Out+"apply.json",JsonConvert.SerializeObject(result,Formatting.Indented));Selection.activeObject=mat;return result;}
}
